#!/usr/bin/env python3
"""Assemble the complete TeX source, optionally compile it with latexmk."""
from __future__ import annotations

import argparse
import os
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[1]


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--compile", action="store_true")
    args = parser.parse_args()
    chunks = [
        "% Complete source generated by code/build_article.py.\n"
        "% Edit the modular source and rebuild, or compile this file directly.\n",
        (ROOT / "preamble.tex").read_text(),
        "\n\\begin{document}\n",
    ]
    for section in sorted((ROOT / "sections").glob("*.tex")):
        chunks += [f"\n% ===== {section.relative_to(ROOT)} =====\n", section.read_text()]
    chunks += ["\n", (ROOT / "references.tex").read_text(), "\n\\end{document}\n"]
    (ROOT / "article.tex").write_text("".join(chunks))
    print("Assembled article.tex", flush=True)
    if args.compile:
        env = os.environ.copy()
        env.setdefault("SOURCE_DATE_EPOCH", "1791624498")
        env.setdefault("TZ", "UTC")
        subprocess.run(
            ["latexmk", "-pdf", "-interaction=nonstopmode", "-halt-on-error", "article.tex"],
            cwd=ROOT, env=env, check=True,
        )


if __name__ == "__main__":
    main()
